// Select rotating weekly nurture content (Milestones, Price Revision Notice, New Phase Announcement)
const itemsOut = [];

for (const item of items) {
  const row = item.json;
  const cleanPhone = String(row.phone || '').replace(/\D/g, '');

  itemsOut.push({
    json: {
      to: '91' + cleanPhone,
      name: row.name,
      project: row.project_name,
      progress: row.construction_progress_pct || 68,
      price: row.price_start || '₹1.45 Cr',
      milestone_video_url: 'https://digireachestates.com/progress-videos',
      template: 'digireach_weekly_nurture_milestone'
    }
  });
}

return itemsOut;

